@prefix : <https://purl.org/geojson/topo#> .
@prefix geojson: <https://purl.org/geojson/vocab#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a geojson:ArcByChord ;
                    :orientation "cw" ;
                    :relatedFeatures ( <http://www.example.com/features/arcP1> <http://www.example.com/features/arcP2> ) ] ;
            sh:resultMessage "An arc by chord or circle by centre has exactly one radius."@en ;
            sh:resultPath geojson:radius ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:maxCount 1 ;
                    sh:message "An arc by chord or circle by centre has exactly one radius."@en ;
                    sh:minCount 1 ;
                    sh:path geojson:radius ] ] .

@prefix : <https://purl.org/geojson/topo#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode _:n31b703ce559d4b61b662b23e9905a01db2 ;
            sh:resultMessage "An oriented reference has exactly one orientation, '+' or '-'."@en ;
            sh:resultPath :orientation ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:InConstraintComponent ;
            sh:sourceShape [ sh:in ( "+" "-" ) ;
                    sh:maxCount 1 ;
                    sh:message "An oriented reference has exactly one orientation, '+' or '-'."@en ;
                    sh:minCount 1 ;
                    sh:path :orientation ] ;
            sh:value "forward" ],
        [ a sh:ValidationResult ;
            sh:focusNode [ a :Ring ;
                    :directedReferences ( [ :orientation "forward" ;
                                :ref <urn:uuid:c60507ba-226b-4e49-a702-e9afef899b23> ] ) ] ;
            sh:resultMessage "Directed references are a non-empty list of oriented references."@en ;
            sh:resultPath ( :directedReferences [ sh:zeroOrMorePath rdf:rest ] rdf:first ) ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:NodeConstraintComponent ;
            sh:sourceShape [ sh:message "Directed references are a non-empty list of oriented references."@en ;
                    sh:minCount 1 ;
                    sh:node :OrientedReferenceShape ;
                    sh:path ( :directedReferences [ sh:zeroOrMorePath rdf:rest ] rdf:first ) ] ;
            sh:value _:n31b703ce559d4b61b662b23e9905a01db2 ] .

_:n31b703ce559d4b61b662b23e9905a01db2 :orientation "forward" ;
    :ref <urn:uuid:c60507ba-226b-4e49-a702-e9afef899b23> .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .
